// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

/// @title IConetProofVerifier
/// @notice Checks CoNET-side messages against a finalized CoNET state. This verifier is the only trust root the
/// treasury relies on for whitelist changes, releases and refunds. The committee-signature path is not modelled here.
interface IConetProofVerifier {
    /// @notice A governance whitelist message. `chainId` and `treasury` bind it to one deployment.
    struct Allowlist {
        uint256 chainId;
        address treasury;
        address token;
        bool add;
        uint256 version;
        uint256 cap;
        bytes32 codeHash;
    }

    /// @notice A CoNET burn that releases `amount` of `token` to `recipient` on this chain.
    struct Burn {
        uint256 chainId;
        address treasury;
        address token;
        address recipient;
        uint256 amount;
        bytes32 burnId;
    }

    /// @notice One proof, at one finalized CoNET block, that the route is disabled and that `depositId` was never minted.
    struct Refund {
        uint256 chainId;
        address treasury;
        bytes32 depositId;
        address token;
        address depositor;
        uint256 amount;
    }

    function verifyAllowlist(bytes calldata proof) external view returns (Allowlist memory);

    function verifyBurn(bytes calldata proof) external view returns (Burn memory);

    function verifyRefund(bytes calldata proof) external view returns (Refund memory);
}

